Count the required opening and closing removals, then search all ways to remove exactly those counts. Keep every non-parenthesis character, never allow negative balance, and select the lexicographically smallest valid result.

```javascript
function solve(s) {
  let removeOpen = 0;
  let removeClose = 0;

  for (const ch of s) {
    if (ch === '(') {
      removeOpen++;
    } else if (ch === ')') {
      if (removeOpen > 0) removeOpen--;
      else removeClose++;
    }
  }

  let best = null;
  const path = [];

  function search(i, balance, openLeft, closeLeft) {
    if (s.length - i < openLeft + closeLeft) return;

    if (i === s.length) {
      if (balance === 0 && openLeft === 0 && closeLeft === 0) {
        const candidate = path.join('');
        if (best === null || candidate < best) best = candidate;
      }
      return;
    }

    const ch = s[i];
    if (ch === '(') {
      if (openLeft > 0) {
        search(i + 1, balance, openLeft - 1, closeLeft);
      }
      path.push(ch);
      search(i + 1, balance + 1, openLeft, closeLeft);
      path.pop();
    } else if (ch === ')') {
      if (closeLeft > 0) {
        search(i + 1, balance, openLeft, closeLeft - 1);
      }
      if (balance > 0) {
        path.push(ch);
        search(i + 1, balance - 1, openLeft, closeLeft);
        path.pop();
      }
    } else {
      path.push(ch);
      search(i + 1, balance, openLeft, closeLeft);
      path.pop();
    }
  }

  search(0, 0, removeOpen, removeClose);
  return best;
}
```

Call `solve(s)` directly with a string. Empty input returns `""`; already balanced input is unchanged. Worst-case time: O(n · 2^p), where p is the number of parentheses and n is the string length. Auxiliary space: O(n), including recursion and candidate storage. This exhaustive implementation is intended for inputs small enough for exponential search and JavaScript’s recursion limit.

